-- Storefront settings (P1-216, 04-api-spec.md §4). One row per shop; every
-- statement names the caller's tenant, and RLS holds it there too.

-- name: EnsureStorefrontSettings :exec
-- A shop made after the backfill gets its row on first use. The webhook id is
-- a random v4, generated by the caller: it sits in a URL.
INSERT INTO storefront_settings (tenant_id, midtrans_webhook_id)
VALUES (current_setting('app.tenant_id')::uuid, sqlc.arg(webhook_id))
ON CONFLICT (tenant_id) DO NOTHING;

-- name: GetStorefrontSettings :one
SELECT * FROM storefront_settings WHERE tenant_id = current_setting('app.tenant_id')::uuid;

-- name: LockStorefrontSettings :one
-- A PATCH validates the merged row under this lock, so two owners saving at
-- once cannot together switch off both payment methods.
SELECT * FROM storefront_settings WHERE tenant_id = current_setting('app.tenant_id')::uuid FOR UPDATE;

-- name: UpdateStorefrontSettings :one
UPDATE storefront_settings SET
    contact_email = sqlc.narg(contact_email),
    google_client_id = sqlc.narg(google_client_id),
    origin_postal_code = sqlc.narg(origin_postal_code),
    shipping_couriers = sqlc.arg(shipping_couriers),
    bank_transfer_enabled = sqlc.arg(bank_transfer_enabled),
    bank_transfer_instructions = sqlc.narg(bank_transfer_instructions),
    midtrans_enabled = sqlc.arg(midtrans_enabled),
    midtrans_environment = sqlc.narg(midtrans_environment),
    midtrans_client_key = sqlc.narg(midtrans_client_key),
    midtrans_server_key = sqlc.narg(midtrans_server_key),
    updated_at = now()
WHERE tenant_id = current_setting('app.tenant_id')::uuid
RETURNING *;
